// Reference solution
function fragment(totalLen, mtu) {
  var data = totalLen - 20, per = Math.floor((mtu - 20) / 8) * 8, off = 0, out = [];
  while (data > 0) {
    var n = Math.min(per, data);
    out.push({ offset: off / 8, dataLen: n, mf: data - n > 0 ? 1 : 0 });
    off += n; data -= n;
  }
  return out;
}
